using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Globalization;using System.Windows.Forms;
namespace BeamScheduleFormatter {
class TrussConnectionForm:DesignSheetForm {
 readonly ComboBox family,profile,grade,threads;readonly CheckBox verified;readonly TextBox area,thickness,offset,table;bool updating;
 public TrussConnectionForm():base("Truss Connections | Workbook axial checks","Truss-Connections"){
  var geometry=Section("Member & demand","Axial/concentric truss connection checks based on the four supplied PS workbooks. Select a handbook profile and verify design section area/thickness. HSS sheets cover welded connections; complete chord/joint limit states and member buckling remain separate.");family=Choice(geometry,"Family","Member family",new[]{"Angle","Double angle","HSS rectangle","HSS circle / pipe"});profile=Choice(geometry,"Profile","Regan handbook profile",SteelCatalog.Profiles.Where(p=>p.Kind=="Angle bar"||p.Kind.StartsWith("HSS")).Select(p=>p.Name).ToArray());geometry.Controls.Add(new SteelSectionPreview(()=>SteelCatalog.Find(profile.Text),()=>family.Text=="Double angle",profile,family));Choice(geometry,"Method","Design method / demand basis",new[]{"LRFD","ASD"});Choice(geometry,"Connection","Connection",new[]{"Weld","Bolts"});NumberField(geometry,"Tension","Axial tension demand kN","0");NumberField(geometry,"Compression","Axial compression demand kN","0");NumberField(geometry,"Fy","Member Fy MPa","248");NumberField(geometry,"Fu","Member Fu MPa","400");verified=Toggle(geometry,"VerifiedProperties","Use verified member geometry",false);area=NumberField(geometry,"Area","Area mm2 PER single angle/member","1");thickness=NumberField(geometry,"Thickness","Member design thickness mm","6");offset=NumberField(geometry,"Offset","Centroid-to-connection offset mm","20");NumberField(geometry,"GussetThickness","Gusset / connected part thickness mm","6");NumberField(geometry,"GussetWidth","Effective gusset width mm","150");NumberField(geometry,"GussetFy","Gusset Fy MPa","248");NumberField(geometry,"GussetFu","Gusset Fu MPa","400");Toggle(geometry,"AllConnected","All cross-section elements connected",false);NumberField(geometry,"U","Verified shear-lag U (0 = derive)","0");
  var weld=Section("Weld detail","Lengths are per single angle/member connection; double-angle multiplicity is applied once. Directional strength increase is optional for a verified concentric uniform-leg longitudinal/transverse weld group. Fillet phi=.75 / Omega=2.00; verify applicable weld detail and exceptions.");NumberField(weld,"Weld","Fillet leg size mm","4");NumberField(weld,"WeldEdge","Thickness at welded edge mm (0=member)","0");NumberField(weld,"Fexx","Electrode Fexx MPa (E70 approx 482.65)","482.65");NumberField(weld,"LT","Transverse weld length mm","0");NumberField(weld,"LL1","Longitudinal weld length 1 mm","100");NumberField(weld,"LL2","Longitudinal weld length 2 mm","100");Toggle(weld,"Directional","Verified directional weld increase",false);weld.Controls.Add(new TrussWeldDrawing(Inputs));
  var bolts=Section("Bolt detail","Single longitudinal bolt row for angle / double-angle to gusset. HSS through-wall bolt and chord-joint checks are not supplied by the source workbooks. Explicit hole diameter is distinct from minimum edge distance. Shear planes must match the actual joint; double angle does not automatically double gusset strength.");grade=Choice(bolts,"Grade","Bolt grade",new[]{"A325","A307"});threads=Choice(bolts,"Threads","Threads at shear plane",new[]{"Included","Excluded"});NumberField(bolts,"Bolts","Number of bolts in one row","3");Choice(bolts,"ShearPlanes","Shear planes per bolt",new[]{"1","2"});NumberField(bolts,"Diameter","Bolt diameter mm","16");NumberField(bolts,"Hole","Specified hole diameter mm","18");NumberField(bolts,"Edge","End / edge distance mm","35");NumberField(bolts,"BoltSpacing","Bolt spacing mm","50");Toggle(bolts,"Exposed","Weather exposed",true);var shear=NumberField(bolts,"Fnv","Nominal bolt shear stress MPa","372");Toggle(bolts,"VerifiedFnv","Use verified nominal shear stress",false);Action updateShear=()=>{bool manual=((CheckBox)Inputs["VerifiedFnv"]).Checked;shear.ReadOnly=!manual;if(!manual)shear.Text=grade.Text=="A307"?"186":threads.Text=="Included"?"372":"457";};grade.SelectedIndexChanged+=(s,e)=>{if(!Restoring)updateShear();};threads.SelectedIndexChanged+=(s,e)=>{if(!Restoring)updateShear();};((CheckBox)Inputs["VerifiedFnv"]).CheckedChanged+=(s,e)=>{if(!Restoring)updateShear();};updateShear();
  var block=Section("Block shear","Optional verified MEMBER block-shear path: enter TOTAL assembly Agv, Anv and Ant in mm2 (do not double again for double angles). Ubs=1 assumes uniform tensile stress. All gusset paths must still be checked separately. Zero entries leave this limit state unverified.");NumberField(block,"Agv","Gross shear path Agv mm2","0");NumberField(block,"Anv","Net shear path Anv mm2","0");NumberField(block,"Ant","Net tension path Ant mm2","0");
  var staad=Section("STAAD forces","STAAD: run analysis > Post Processing > Beam End Forces / Envelope; select required members and matching load cases/combinations; set displayed force/moment units; copy the table INCLUDING headers. Paste below or import a CSV/TSV export. Unlike the original workbook, import reads headers and all selected rows rather than assuming the first two Fx cells are the envelope.");Choice(staad,"ForceUnit","STAAD force unit",new[]{"kN","N","kip"});Choice(staad,"MomentUnit","STAAD moment unit",new[]{"kN-m","N-mm","kip-ft"});NumberField(staad,"Members","Member IDs / design group (comma-separated)","");Toggle(staad,"UseStaad","Use the pasted STAAD force table",false);Toggle(staad,"LoadBasis","Selected loads match LRFD/ASD basis",false);table=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Width=1030,Height=260,Tag="FullWidth",Font=new Font("Consolas",9)};Inputs.Add("STAADTable",table);staad.Controls.Add(table);var actions=new FlowLayoutPanel{Width=1030,Height=48,Tag="FullWidth"};var paste=new Button{Text="Paste STAAD table",AutoSize=true};paste.Click+=(s,e)=>{if(Clipboard.ContainsText())table.Text=Clipboard.GetText();};var import=new Button{Text="Import CSV / TSV",AutoSize=true};import.Click+=(s,e)=>{using(var dialog=new OpenFileDialog{Filter="STAAD table|*.csv;*.tsv;*.txt"})if(dialog.ShowDialog(this)==DialogResult.OK)table.Text=System.IO.File.ReadAllText(dialog.FileName);};actions.Controls.AddRange(new Control[]{paste,import});staad.Controls.Add(actions);
  family.SelectedIndexChanged+=(s,e)=>{if(Restoring||updating)return;updating=true;try{string kind=family.Text=="Angle"||family.Text=="Double angle"?"Angle bar":family.Text;profile.SelectedItem=SteelCatalog.Profiles.First(p=>p.Kind==kind).Name;if(family.Text.StartsWith("HSS"))Inputs["Connection"].Text="Weld";}finally{updating=false;}UpdateProperties();};profile.SelectedIndexChanged+=(s,e)=>{if(!Restoring&&!updating)UpdateProperties();};verified.CheckedChanged+=(s,e)=>{if(!Restoring)UpdateProperties();};profile.SelectedItem="L75x75x6mm (PNS)";UpdateProperties();
 }
 void UpdateProperties(){var p=SteelCatalog.Find(profile.Text);if(p==null)return;double a,x;if(p.Kind=="Angle bar"){a=(p.H+p.B-p.T)*p.T;x=(p.B*p.T*p.B/2+(p.H-p.T)*p.T*p.T/2)/a;}else if(p.Kind=="HSS rectangle"){a=p.H*p.B-(p.H-2*p.T)*(p.B-2*p.T);x=(p.B*p.B+2*p.B*p.H)/(4*(p.B+p.H));}else{a=Math.PI*(p.H*p.H-Math.Pow(p.H-2*p.T,2))/4;x=p.H/Math.PI;}if(!verified.Checked){area.Text=a.ToString("R",CultureInfo.InvariantCulture);thickness.Text=p.T.ToString("R",CultureInfo.InvariantCulture);offset.Text=x.ToString("R",CultureInfo.InvariantCulture);}foreach(var text in new[]{area,thickness,offset})text.ReadOnly=!verified.Checked;}
 protected override void AfterRestore(){UpdateProperties();((TextBox)Inputs["Fnv"]).ReadOnly=!((CheckBox)Inputs["VerifiedFnv"]).Checked;}
 protected override string BuildReport(){var selected=SteelCatalog.Find(profile.Text);string expected=family.Text=="Angle"||family.Text=="Double angle"?"Angle bar":family.Text;if(selected==null||selected.Kind!=expected)throw new Exception("Select a handbook profile matching the member family.");double tension=Number("Tension"),compression=Number("Compression");if(tension<0||compression<0)throw new Exception("Enter nonnegative demand magnitudes.");string forceReport="Manual axial demand magnitudes.\n";if(((CheckBox)Inputs["UseStaad"]).Checked){if(!((CheckBox)Inputs["LoadBasis"]).Checked)throw new Exception("Confirm the STAAD load selection matches LRFD/ASD demand basis.");var rows=StaadForces.Select(StaadForces.Parse(table.Text,Value("ForceUnit"),Value("MomentUnit")),Value("Members"));double envelope=rows.Max(r=>Math.Abs(r.Fx));tension=compression=envelope;forceReport="STAAD: end-sign-independent absolute Fx envelope = "+envelope.ToString("0.###",CultureInfo.InvariantCulture)+"kN applied conservatively to the listed axial checks.\n";foreach(var row in rows)forceReport+=string.Format(CultureInfo.InvariantCulture,"Member {0}, node {1}, LC {2}: Fx {3:0.######}kN; Fy/Fz {4:0.######}/{5:0.######}kN; Mx/My/Mz {6:0.######}/{7:0.######}/{8:0.######}kN-m\n",row.Member,row.Node,row.LoadCase,row.Fx,row.Fy,row.Fz,row.Mx,row.My,row.Mz);if(rows.Any(r=>Math.Abs(r.Fy)+Math.Abs(r.Fz)+Math.Abs(r.Mx)+Math.Abs(r.My)+Math.Abs(r.Mz)>1e-8))forceReport+="NONAXIAL COMPONENTS PRESENT: this sheet does not check combined shear/moment/eccentric demand; listed axial results are not a complete connection approval.\n";}
  double demand=Math.Max(tension,compression);if(demand<=0)throw new Exception("Enter a positive axial demand or import matching STAAD forces.");var input=new ConnectionInput{Family=family.Text,Method=Value("Method"),Connection=Value("Connection"),Grade=Value("Grade"),Area=Number("Area"),Thickness=Number("Thickness"),Offset=Number("Offset"),Fy=Number("Fy"),Fu=Number("Fu"),GussetFy=Number("GussetFy"),GussetFu=Number("GussetFu"),GussetThickness=Number("GussetThickness"),GussetWidth=Number("GussetWidth"),Demand=demand,VerifiedU=Number("U"),AllElementsConnected=((CheckBox)Inputs["AllConnected"]).Checked,VerifiedProperties=verified.Checked,Weld=Number("Weld"),WeldEdgeThickness=Number("WeldEdge"),Fexx=Number("Fexx"),LT=Number("LT"),LL1=Number("LL1"),LL2=Number("LL2"),DirectionalWeldIncrease=((CheckBox)Inputs["Directional"]).Checked,Bolts=Whole("Bolts"),ShearPlanes=int.Parse(Value("ShearPlanes")),BoltDiameter=Number("Diameter"),HoleDiameter=Number("Hole"),EdgeDistance=Number("Edge"),Spacing=Number("BoltSpacing"),Fnv=Number("Fnv"),Exposed=((CheckBox)Inputs["Exposed"]).Checked,Agv=Number("Agv"),Anv=Number("Anv"),Ant=Number("Ant")};return TrussConnectionDesigner.Report(input,TrussConnectionDesigner.Calculate(input),selected.Name,selected.Source)+"\nSTAAD / DEMAND AUDIT\n"+forceReport+"Bentley sign reference: https://bentleysystems.service-now.com/community?id=kb_article_view&sysparm_article=KB0115216";
 }
 int Whole(string key){double value=Number(key);if(value!=Math.Truncate(value)||value<1||value>100000)throw new Exception(key+" must be a positive whole number.");return (int)value;}
}
}
